; ---- setBallSpeedY( yOffset )
        mov     ax, [hitPaddle__yOffset]
        mov     [setBallSpeedY__yOffset], ax
        call    setBallSpeedY
; ---- if ( iabs( ballSpeedX ) < ballSpeedXMax ) {
        mov     ax, [ballSpeedX]
        test    ax, ax
        jl      .L172                       ; signed <
        jmp     .L170
.L172:
        mov     ax, [ballSpeedX]
        neg     ax
        jmp     .L171
.L170:
        mov     ax, [ballSpeedX]
.L171:
        cmp     ax, 9
        jl      .L173                       ; signed <
        jmp     .L168
.L173:
; ---- volleyCount++
        inc     byte [volleyCount]
; ---- if ( volleyCount == volleyTarget ) {
        mov     al, [volleyCount]
        cmp     al, 3                       ; byte operands, no widening
        je      .L176                       ; unsigned ==
        jmp     .L174
.L176:
; ---- volleyCount = 0
        mov     byte [volleyCount], 0
; ---- if ( ballSpeedX > 0 ) ballSpeedX += ballSpeedStep
        mov     ax, [ballSpeedX]
        test    ax, ax
        jg      .L179                       ; signed >
        jmp     .L177
.L179:
        mov     ax, [ballSpeedX]
        add     ax, 3
        mov     [ballSpeedX], ax
        jmp     .L178
.L177:
; ---- else ballSpeedX -= ballSpeedStep
        mov     ax, [ballSpeedX]
        sub     ax, 3
        mov     [ballSpeedX], ax
.L178:
.L174:
.L168:
; ---- ballSpeedX = -ballSpeedX
        mov     ax, [ballSpeedX]
        neg     ax
        mov     [ballSpeedX], ax
; ---- ballPlayer = pi
        mov     al, [hitPaddle__pi]
        mov     [ballPlayer], al            ; u8 -> u8, no widening
; ---- ballColor = paddleColor[ pi ]
        mov     al, [hitPaddle__pi]
        xor     ah, ah                      ; u8 -> u16
        mov     bx, ax
        mov     al, [paddleColor + bx]
        mov     [ballColor], al             ; u8 -> u8, no widening
        ret

; ============================================== sub update ====

update:
; ---- if( isWinScreen ) return
        mov     al, [isWinScreen]
        test    al, al
        jnz     .L182
        jmp     .L180
.L182:
        ret
.L180:
; ---- ballX += ballSpeedX
        mov     ax, [ballX]
        mov     bx, [ballSpeedX]
        add     ax, bx
        mov     [ballX], ax
; ---- ballY += ballSpeedY
        mov     ax, [ballY]
        mov     bx, [ballSpeedY]
        add     ax, bx
        mov     [ballY], ax
; ---- if( ballY < 0 ){
        mov     ax, [ballY]
        test    ax, ax
        jl      .L185                       ; signed <
        jmp     .L183
.L185:
; ---- ballY = 0
        mov     word [ballY], 0
; ---- ballSpeedY = -ballSpeedY
        mov     ax, [ballSpeedY]
        neg     ax
        mov     [ballSpeedY], ax
        jmp     .L184
.L183:
; ---- } else if( ballY > ballYMax ){
        mov     ax, [ballY]
        cmp     ax, 268
        jg      .L188                       ; signed >
        jmp     .L186
.L188:
; ---- ballY = ballYMax
        mov     word [ballY], 268
; ---- ballSpeedY = -ballSpeedY
        mov     ax, [ballSpeedY]
        neg     ax
        mov     [ballSpeedY], ax
.L186:
.L184:
; ---- if( ballSpeedX > 0 && ballX >= ballXMax ){
        mov     ax, [ballSpeedX]
        test    ax, ax
        jg      .L191                       ; signed >
        jmp     .L189
.L191:
        mov     ax, [ballX]
        cmp     ax, 296
        jge     .L192                       ; signed >=
        jmp     .L189
.L192:
; ---- hitPaddle( rightPlayer )
        mov     byte [hitPaddle__pi], 1
        call    hitPaddle
        jmp     .L190
.L189:
; ---- } else if ( ballSpeedX < 0 && ballX <= 0 ){
        mov     ax, [ballSpeedX]
        test    ax, ax
        jl      .L195                       ; signed <
        jmp     .L193
.L195:
        mov     ax, [ballX]
        test    ax, ax
        jle     .L196                       ; signed <=
        jmp     .L193
.L196:
; ---- hitPaddle( leftPlayer )
        mov     byte [hitPaddle__pi], 0
        call    hitPaddle
.L193:
.L190:
        ret

; ============================================== sub render ====

render:
; ---- if( isWinScreen ) return
        mov     al, [isWinScreen]
        test    al, al
        jnz     .L199
        jmp     .L197
.L199:
        ret
.L197:
; ---- clearBall()
        call    clearBall
; ---- clearPaddle( leftPlayer )
        mov     byte [clearPaddle__pi], 0
        call    clearPaddle
; ---- clearPaddle( rightPlayer )
        mov     byte [clearPaddle__pi], 1
        call    clearPaddle
; ---- if ( oBallX >= netBallXMin && oBallX <= netBallXMax ) drawNet()
        mov     ax, [oBallX]
        cmp     ax, 144
        jge     .L202                       ; signed >=
        jmp     .L200
.L202:
        mov     ax, [oBallX]
        cmp     ax, 155
        jle     .L203                       ; signed <=
        jmp     .L200
.L203:
        call    drawNet
.L200:
; ---- drawBall()
        call    drawBall
; ---- drawPaddle( leftPlayer )
        mov     byte [drawPaddle__pi], 0
        call    drawPaddle
; ---- drawPaddle( rightPlayer )
        mov     byte [drawPaddle__pi], 1
        call    drawPaddle
; ---- player[ leftPlayer ].oldY = player[ leftPlayer ].y
        mov     ax, [player__y]
        mov     [player__oldY], ax
; ---- player[ rightPlayer ].oldY = player[ rightPlayer ].y
        mov     ax, [player__y + 2]
        mov     [player__oldY + 2], ax
; ---- oBallX = ballX
        mov     ax, [ballX]
        mov     [oBallX], ax
; ---- oBallY = ballY
        mov     ax, [ballY]
        mov     [oBallY], ax
        ret

; ============================================== sub waitRetrace ====

waitRetrace:
; ---- while ( inRetrace() ) pollKeyboard()
.L204:
        call    inRetrace
        mov     al, [inRetrace__ret]
        xor     ah, ah                      ; bool -> u16
        test    ax, ax
        jnz     .L207
        jmp     .L206
.L207:
        call    pollKeyboard
.L205:
        jmp     .L204
.L206:
; ---- while ( !inRetrace() ) pollKeyboard()
.L208:
        call    inRetrace
        mov     al, [inRetrace__ret]
        xor     ah, ah                      ; bool -> u16
        test    ax, ax
        jz      .L211
        jmp     .L210
.L211:
        call    pollKeyboard
.L209:
        jmp     .L208
.L210:
        ret

; ============================================== sub waitFrame ====

waitFrame:
; ---- waitRetrace()
        call    waitRetrace
; ---- waitRetrace()
        call    waitRetrace
        ret

; ============================================== sub tick ====

tick:
; ---- input()
        call    input
; ---- update()
        call    update
; ---- waitFrame()
        call    waitFrame
; ---- render()
        call    render
        ret

; ============================================== sub win ====

win:
; ---- isWinScreen = true
        mov     byte [isWinScreen], 1
; ---- waitFrame()
        call    waitFrame
; ---- drawBackground( winColor[ pi ] )
        mov     al, [win__pi]
        xor     ah, ah                      ; u8 -> u16
        shl     ax, 1                       ; word elements
        mov     bx, ax
        mov     ax, [winColor + bx]
        mov     [drawBackground__color], ax
        call    drawBackground
; ---- drawScore( leftPlayer )
        mov     byte [drawScore__pi], 0
        call    drawScore
; ---- drawScore( rightPlayer )
        mov     byte [drawScore__pi], 1
        call    drawScore
        ret

; ============================================== sub serve ====

serve:
; ---- ballSpeedY = 0
        mov     word [ballSpeedY], 0
; ---- volleyCount = 0
        mov     byte [volleyCount], 0
; ---- ballX = serveX[ ballPlayer ]
        mov     al, [ballPlayer]
        xor     ah, ah                      ; u8 -> u16
        shl     ax, 1                       ; word elements
        mov     bx, ax
        mov     ax, [serveX + bx]
        mov     [ballX], ax
; ---- ballY = player[ ballPlayer ].y + ballServeOffset
        mov     al, [ballPlayer]
        xor     ah, ah                      ; u8 -> u16
        shl     ax, 1                       ; word elements
        mov     bx, ax
        mov     ax, [player__y + bx]
        add     ax, 12
        mov     [ballY], ax
; ---- ballSpeedX = serveSpeedX[ ballPlayer ]
        mov     al, [ballPlayer]
        xor     ah, ah                      ; u8 -> u16
        shl     ax, 1                       ; word elements
        mov     bx, ax
        mov     ax, [serveSpeedX + bx]
        mov     [ballSpeedX], ax
; ---- ballColor = paddleColor[ ballPlayer ]
        mov     al, [ballPlayer]
        xor     ah, ah                      ; u8 -> u16
        mov     bx, ax
        mov     al, [paddleColor + bx]
        mov     [ballColor], al             ; u8 -> u8, no widening
        ret

; ============================================== sub start ====

start:
; ---- seedRandom( ticks() )
        call    ticks
        mov     ax, [ticks__ret]
        mov     [seedRandom__s], ax
        call    seedRandom
; ---- isWinScreen = false
        mov     byte [isWinScreen], 0
; ---- player[ leftPlayer ].speed = 0
        mov     byte [player__speed], 0
; ---- player[ leftPlayer ].score = 0
        mov     byte [player__score], 0
; ---- player[ leftPlayer ].y = paddleYHome
        mov     word [player__y], 122
; ---- player[ leftPlayer ].oldY = paddleYHome
        mov     word [player__oldY], 122
; ---- player[ rightPlayer ].speed = 0
        mov     byte [player__speed + 1], 0
; ---- player[ rightPlayer ].score = 0
        mov     byte [player__score + 1], 0
; ---- player[ rightPlayer ].y = paddleYHome
        mov     word [player__y + 2], 122
; ---- player[ rightPlayer ].oldY = paddleYHome
        mov     word [player__oldY + 2], 122
; ---- ballPlayer = randomBelow( len( player ) )
        mov     word [randomBelow__n], 2
        call    randomBelow
        mov     ax, [randomBelow__ret]
        mov     [ballPlayer], al            ; narrowed to u8
; ---- waitFrame()
        call    waitFrame
; ---- drawBackground( lightGreenW )
        mov     word [drawBackground__color], 257
        call    drawBackground
; ---- drawPlayfield()
        call    drawPlayfield
; ---- drawScore( leftPlayer )
        mov     byte [drawScore__pi], 0
        call    drawScore
; ---- drawScore( rightPlayer )
        mov     byte [drawScore__pi], 1
        call    drawScore
; ---- serve()
        call    serve
; ---- oBallX = ballX
        mov     ax, [ballX]
        mov     [oBallX], ax
; ---- oBallY = ballY
        mov     ax, [ballY]
        mov     [oBallY], ax
        ret

; ==================================================== int helpers ====
; One per distinct interrupt: the literal is baked in, so the register
; sync is emitted once rather than at every call site.

int10:
        push    es
        mov     ax, [_ax]
        mov     bx, [_bx]
        mov     cx, [_cx]
        mov     dx, [_dx]
        mov     si, [_si]
        mov     di, [_di]
        int     0x10
        mov     [_ax], ax
        mov     [_bx], bx
        mov     [_cx], cx
        mov     [_dx], dx
        mov     [_si], si
        mov     [_di], di
        pop     es
        ret

int21:
        push    es
        mov     ax, [_ax]
        mov     bx, [_bx]
        mov     cx, [_cx]
        mov     dx, [_dx]
        mov     si, [_si]
        mov     di, [_di]
        int     0x21
        mov     [_ax], ax
        mov     [_bx], bx
        mov     [_cx], cx
        mov     [_dx], dx
        mov     [_si], si
        mov     [_di], di
        pop     es
        ret

